#include <stdio.h>
int main(void) {
    FILE *s = fopen("src.bin", "wb");
    for (int i = 0; i < 10; i++) { unsigned char c = (unsigned char)i; fwrite(&c, 1, 1, s); }
    fclose(s);
    FILE *src = fopen("src.bin", "rb");
    FILE *dst = fopen("dst.bin", "wb");
    unsigned char buf[4];
    size_t total = 0, k;
    while ((k = fread(buf, 1, sizeof buf, src)) > 0) { fwrite(buf, 1, k, dst); total += k; }
    fclose(src); fclose(dst);
    printf("copied %zu bytes\n", total);
    return 0;
}
